-- 0003_auth_revocations.sql - durable refresh family/session revocation tombstones.
-- Forward-only migration: there is intentionally no down migration.
--
-- A tombstone records that a whole refresh-token family or session was revoked.
-- Tombstones have no expiry and are never pruned: deleting expired
-- refresh_tokens rows must not resurrect a family or session revoked earlier.
--
-- scope_id is an opaque family/session identifier generated by the auth layer
-- (random ids, no user data). The adapter trims surrounding whitespace before
-- inserting, so tombstone keys and refresh_tokens rows share one canonical
-- value.
--
-- No backfill is needed: schema version 2 (refresh_tokens) was never deployed
-- in production, so there are no pre-existing families or sessions that would
-- require tombstones.

CREATE TABLE IF NOT EXISTS auth_revocations (
    scope_kind text NOT NULL,
    scope_id text NOT NULL,
    revoked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (scope_kind, scope_id),
    CONSTRAINT auth_revocations_scope_kind_check CHECK (scope_kind IN ('family', 'session')),
    CONSTRAINT auth_revocations_scope_id_check CHECK (btrim(scope_id) <> '')
);
CREATE INDEX IF NOT EXISTS auth_revocations_revoked_idx ON auth_revocations (revoked_at DESC);
